import React, { useState, useRef, useEffect } from 'react';
import { BrowserRouter as Router, Route, Routes, Link, useNavigate, useLocation } from 'react-router-dom';
import './App.css';
// import './animations.css'; // No longer needed, styles are added dynamically
import Breadcrumb from './Breadcrumb';
import CategoryPage from './CategoryPage';
import NewPage from './NewPage';
import CoolPage from './CoolPage';
import PopularPage from './PopularPage';
import StatsPage from './StatsPage';
import InteractiveMenu from './InteractiveMenu';
import { categories, Category, getCategoryById } from './data/categories';
import AnimatedContent from './components/AnimatedContent';
import { motion, useAnimation, Variants } from 'framer-motion';

// Main app content with navigation
const AppContent: React.FC = () => {
  const [path, setPath] = useState<string[]>([]);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const pageSearchInputRef = useRef<HTMLInputElement>(null);
  const mainContentRef = useRef<HTMLDivElement>(null);
  const navigate = useNavigate();
  const location = useLocation();

  const handleNavigate = (categoryId: string) => {
    setPath([...path, categoryId]);
  };

  const handleBreadcrumbClick = (index: number) => {
    setPath(path.slice(0, index + 1));
  };

  const handleReset = () => {
    setPath([]);
  };

  const handleBack = () => {
    window.history.back();
  };

  const handleForward = () => {
    window.history.forward();
  };

  const handleHome = () => {
    setPath([]);
    navigate('/');
  };

  const currentCategory: Category | undefined = path.length
    ? getCategoryById(path[path.length - 1])
    : undefined;

  const displayText = path.length
    ? currentCategory?.name || 'Unknown Category'
    : 'A Guide to WWW';

  const currentUrl = path.length
    ? `alien/${path.join('/')}`
    : 'alien/';

  // Create route key for animation triggering
  const routeKey = location.pathname + path.join('-');

  // Categories component that strictly animates one category at a time
  const MainContent: React.FC = () => {
    const [animatingIndex, setAnimatingIndex] = useState<number>(-1);
    const [completedCategories, setCompletedCategories] = useState<Category[]>([]);
    const [currentCategory, setCurrentCategory] = useState<Category | null>(null);
    const [currentText, setCurrentText] = useState<string>("");
    const controls = useAnimation();

    // This effect manages the sequential animation
    useEffect(() => {
      // Start with -1 to initialize
      if (animatingIndex === -1 && categories.length > 0) {
        // Start with the first category
        setAnimatingIndex(0);
        setCurrentCategory(categories[0]);
        setCurrentText(categories[0].name);
      } else if (animatingIndex >= 0 && animatingIndex < categories.length) {
        // Animate the current category
        const animate = async () => {
          await controls.start("visible");

          // Once animation completes, add to completed list and move to next
          setCompletedCategories(prev => [...prev, categories[animatingIndex]]);

          if (animatingIndex + 1 < categories.length) {
            // Small pause between categories
            await new Promise(resolve => setTimeout(resolve, 200));

            // Move to next category
            setAnimatingIndex(animatingIndex + 1);
            setCurrentCategory(categories[animatingIndex + 1]);
            setCurrentText(categories[animatingIndex + 1].name);
          }
        };

        animate();
      }
    }, [animatingIndex, controls]);

    // Character animation variants
    const container: Variants = {
      hidden: { opacity: 1 },
      visible: {
        opacity: 1,
        transition: {
          staggerChildren: 0.025,
          delayChildren: 0.01
        }
      }
    };

    const child: Variants = {
      hidden: { opacity: 0, display: "inline-block" },
      visible: { 
        opacity: 1, 
        display: "inline-block",
        transition: { duration: 0.01 }
      }
    };

    // Render both completed categories (static) and the currently animating one
    return (
      <div className="categories">
        <ul className="categories-list">
          {/* Previously completed categories (already animated) */}
          {completedCategories.map((category) => (
            <li key={category.id} className="category-item">
              <span className="bullet">•</span>
              <Link
                to={`/category/${category.id}`}
                onClick={() => handleNavigate(category.id)}
              >
                {category.name}
              </Link>
              <span className="count">
                ({category.count})
              </span>
              {category.isNew && <img src="/new.gif" alt="New" className="new-badge" />}
            </li>
          ))}

          {/* Currently animating category */}
          {currentCategory && (
            <li key={currentCategory.id} className="category-item">
              <span className="bullet">•</span>
              <Link
                to={`/category/${currentCategory.id}`}
                onClick={() => handleNavigate(currentCategory.id)}
              >
                <motion.span
                  variants={container}
                  initial="hidden"
                  animate={controls}
                  className="typewriter-text"
                >
                  {Array.from(currentText).map((char, i) => (
                    <motion.span
                      key={`${i}-${char}`}
                      variants={child}
                      className="typewriter-char"
                    >
                      {char === ' ' ? '\u00A0' : char}
                    </motion.span>
                  ))}
                </motion.span>
              </Link>
              <span className="count">
                ({currentCategory.count})
              </span>
              {currentCategory.isNew && <img src="/new.gif" alt="New" className="new-badge" />}
            </li>
          )}
        </ul>
      </div>
    );
  };

  return (
    <div className="app">
      <div className="header">
        <div className="title-bar">
          <div className="window-controls">
            <button className="window-button"></button>
          </div>
          <div className="window-title">NeXT - Alien</div>
          <div className="window-controls-right">
            <button className="window-button"></button>
          </div>
        </div>

        <div className="sub-bar">
          <div className="search-icon">
            <img src="/img/nextstep/find-icon.png" alt="" className="fallback-find-icon" />
          </div>
          <div className="sub-bar-search">
            <input 
              type="text" 
              placeholder="Search in page..." 
              ref={pageSearchInputRef} 
              id="page-search-input" 
            />
          </div>
        </div>

        <div className="navbar">
          <button title="Globe" className="nav-button">
            <img src="/img/nextstep/globe.png" alt="Globe" className="nav-icon fallback-globe" />
          </button>
          <button title="Back" className="nav-button" onClick={handleBack}>
            <img src="/img/nextstep/back.png" alt="Back" className="nav-icon fallback-back" />
          </button>
          <button title="Forward" className="nav-button" onClick={handleForward}>
            <img src="/img/nextstep/forward.png" alt="Forward" className="nav-icon fallback-forward" />
          </button>
          <button title="Home" className="nav-button" onClick={handleHome}>
            <img src="/img/nextstep/home.png" alt="Home" className="nav-icon fallback-home" />
          </button>
          <button title="Bookmark Menu" className="nav-button">
            <img src="/img/nextstep/bookmark-menu.png" alt="Bookmark Menu" className="nav-icon fallback-bookmark-menu" />
          </button>
          <button title="Add Bookmark" className="nav-button">
            <img src="/img/nextstep/add-bookmark.png" alt="Add Bookmark" className="nav-icon fallback-add-bookmark" />
          </button>
          <button title="Search" className="nav-button">
            <img src="/img/nextstep/search.png" alt="Search" className="nav-icon fallback-search" />
          </button>
          <button title="Navigate" className="nav-button">
            <img src="/img/nextstep/navigate.png" alt="Navigate" className="nav-icon fallback-navigate" />
          </button>
          <button title="Settings" className="nav-button">
            <img src="/img/nextstep/settings.png" alt="Settings" className="nav-icon fallback-settings" />
          </button>
          <button title="Info" className="nav-button">
            <img src="/img/nextstep/info.png" alt="Info" className="nav-icon fallback-info" />
          </button>
          <button title="Print" className="nav-button">
            <img src="/img/nextstep/print.png" alt="Print" className="nav-icon fallback-print" />
          </button>
        </div>

        <div className="url-bar">
          <div className="url-icon">
            <img src="/img/nextstep/url-icon.png" alt="" className="fallback-url-icon" />
          </div>
          <input 
            type="text" 
            value={currentUrl} 
            placeholder="alien/" 
            readOnly 
            ref={searchInputRef} 
            id="search-input" 
          />
        </div>
      </div>
      <div className="main-content" ref={mainContentRef}>
        <h1>
          <Link to="/" onClick={handleReset} className="alien-title">
            <span className="alien-text">Alien</span>
          </Link>
          &nbsp;- {displayText}
        </h1>
        <Breadcrumb path={path} onClick={handleBreadcrumbClick} />
        <div className="sub-links">
          [
          <Link to="/new">What's New?</Link> | 
          <Link to="/cool">What's Cool?</Link> | 
          <Link to="/popular">What's Popular?</Link> | 
          <Link to="/stats">Stats</Link> | 
          <Link to="/random">A Random Link</Link>]
        </div>
        <div style={{ marginBottom: '15px' }}>
          <InteractiveMenu />
        </div>
        <AnimatedContent routeKey={routeKey}>
          <Routes>
            <Route path="/" element={<MainContent />} />
            <Route path="/category/:categoryId" element={
              <CategoryPage
                category={currentCategory?.id || ''}
                onNavigate={handleNavigate}
              />
            } />
            <Route path="/new" element={<NewPage onNavigate={handleNavigate} />} />
            <Route path="/cool" element={<CoolPage onNavigate={handleNavigate} />} />
            <Route path="/popular" element={<PopularPage onNavigate={handleNavigate} />} />
            <Route path="/stats" element={<StatsPage />} />
          </Routes>
        </AnimatedContent>
      </div>
      <div className="footer">
        <b>23836</b> entries in <i>Alien</i> | <Link to="#"><i>Alien</i></Link> | <Link to="#"><i>Up</i></Link> | <Link to="#"><i>Search</i></Link> | <Link to="#"><i>Mail</i></Link> | <Link to="#"><i>Add</i></Link> | <Link to="#"><i>Help</i></Link>
        <p><a href="mailto:feedback@alien.com">feedback@alien.com</a></p>
        <p>Copyright © 1994 Antimeme and Bias Research Ltd.</p>
      </div>
    </div>
  );
};

// Main App component wrapper
const App: React.FC = () => {
  return (
    <Router>
      <AppContent />
    </Router>
  );
};

export default App;
